// "SRP" refactor of a checkout total — every change so far has touched all of these together
 class SubtotalCalculator { calc(items: Item[]) { return items.reduce((s, i) => s + i.price * i.qty, 0); } }
 class TaxCalculator { calc(amount: number) { return amount * 0.2; } }
 class DiscountCalculator { calc(amount: number) { return amount * 0; } } // discounts not used yet
 class RoundingPolicy { round(n: number) { return Math.round(n * 100) / 100; } }
 class TotalAssembler {
   constructor(private sub: SubtotalCalculator, private tax: TaxCalculator,
               private disc: DiscountCalculator, private round: RoundingPolicy) {}
   total(items: Item[]) {
     const s = this.sub.calc(items);
     return this.round.round(s + this.tax.calc(s) - this.disc.calc(s));
   }
 }
 // Meanwhile the SQL that persists the total still lives inlined in CheckoutController.handle()
